#!/usr/bin/env python3
"""Make upstream's autogenerated api_marshal_fuzzer.go compile at this commit.

The generator (go/test/fuzzing/autogenerate) is bit-rotted: it imports the removed
go/vt/proto/automation package and emits `&.Type{}` (empty package qualifier) for types in
packages it could not name. Drop that import, drop those functions and their switch cases,
and rename the package.  usage: fix_api_marshal.py <in.go> <out.go> <package>
"""
import re
import sys

src, dst, pkg = sys.argv[1:4]
s = open(src).read()
s = s.replace('\tautomation "vitess.io/vitess/go/vt/proto/automation"\n', '')
s = re.sub(r'(?m)^package \w+', 'package ' + pkg, s, count=1)
bad = set()
out = []
for p in re.split(r'(?m)^(?=func )', s):
    m = re.match(r'func (\w+)\(', p)
    if m and re.search(r'&\.[A-Za-z]', p):
        bad.add(m.group(1))
        continue
    out.append(p)
s = ''.join(out)
for b in bad:
    s = re.sub(r'\tcase \d+:\n\t\t_ = %s\(data2\)\n\n?' % b, '', s)
open(dst, 'w').write(s)
print('dropped %d unusable generated funcs' % len(bad))
